import React from 'react';
import CustomNav from '../CustomsNav';
import { userData } from '../../helpers';
import { useProducts } from './useProduct';
import { Row, Col } from "reactstrap";
import Product from './Product';

const Home = () => {
  const { username } = userData();
  const { categories, products } = useProducts();

  console.log({ categories });
  console.log({ products });

  return (
    <div>
      <CustomNav />
      <div className="Home">
        <h2 style={{ textAlign: "center" }}>Enjoy our sales, {username}!</h2>

        {categories.length
          ? categories.map((category) => {
              const hasProducts = products.filter(
                (product) => 
                  product.attributes.category &&
                  product.attributes.category.data &&
                  product.attributes.category.data.id === category.id
              );

              return hasProducts && hasProducts.length ? (
                <React.Fragment key={category.id}>
                  <h2 className="category-title">{category.attributes.name}</h2>
                  <Row className="category">
                    {hasProducts.map((product) => (
                      <Col sm="12" md="4" key={product.id}>
                        <Product product={product} />
                      </Col>
                    ))}
                  </Row>
                </React.Fragment>
              ) : null;
            })
          : <p style={{ textAlign: "center" }}>No categories or products available</p>}
      </div>
    </div>
  );
};

export default Home;
